 chat=["P: どうしましたか。 | O que houve? | dō shimashita ka.",
  "Y: 駅で財布をぬすまれました。 | Roubaram minha carteira na estação. | eki de saifu o nusumaremashita.",
  "P: いつ気がつきましたか。 | Quando percebeu? | itsu ki ga tsukimashita ka.",
  "Y: 電車を降りたとき、かばんが開けられていました。 | Quando desci do trem, a bolsa estava aberta. | densha o orita toki, kaban ga akerarete imashita.",
  "P: 何が入っていましたか。 | O que havia dentro? | nani ga haitte imashita ka.",
  "Y: 現金と、カードと、学生証です。 | Dinheiro, cartões e carteirinha de estudante. | genkin to, kādo to, gakuseishō desu.",
  "P: カードは止めましたか。 | Já bloqueou os cartões? | kādo wa tomemashita ka.",
  "Y: はい、さっき電話しました。 | Sim, liguei agora há pouco. | hai, sakki denwa shimashita.",
  "P: では、この紙に名前と電話番号を書いてください。 | Então escreva nome e telefone neste papel. | dewa, kono kami ni namae to denwa bangō o kaite kudasai.",
  "Y: はい。見つかったら、連絡をもらえますか。 | Sim. Se acharem, posso receber um contato? | hai. mitsukattara, renraku o moraemasu ka.",
  "P: ええ、見つかったらすぐお知らせします。 | Sim, aviso assim que encontrarem. | ē, mitsukattara sugu oshirase shimasu."],
 tap=[("ヤマさんは 何を ぬすまれましたか。","O que roubaram de Yama?",["財布","傘","スマホ"],0,1,"Y: “財布をぬすまれました”"),
  ("かばんは どう なっていましたか。","Como estava a bolsa?",["こわされていた","開けられていた","なくなっていた"],1,3,"Y: “かばんが開けられていました”"),
  ("カードは どうしましたか。","O que fez com os cartões?",["使った","わすれた","止めた"],2,7,"Y: “さっき電話しました”")],
 swap=("Passiva de pessoa e de coisa: «財布を ぬすまれた» (sofri o roubo) e «かばんが 開けられていた» (a bolsa estava aberta). 🎓 JLPT N4 / JF A2: 受身.",
  [("…を ぬすまれました。",[("財布を","A carteira"),("かばんを","A bolsa"),("自転車を","A bicicleta")],[("ぬすまれました","foi roubada"),("とられました","foi levada"),("こわされました","foi quebrada")],"。"),
   ("…られて いました。",[("かばんが","A bolsa"),("まどが","A janela"),("ドアが","A porta")],[("開けられて いました","estava aberta"),("閉められて いました","estava fechada"),("こわされて いました","estava quebrada")],"。")]),
 chat2=["Y: すみません、さっき電車で財布をぬすまれました。 | Com licença, roubaram minha carteira no trem agora há pouco. | sumimasen, sakki densha de saifu o nusumaremashita.",
  "P: 落ち着いてください。どこで降りましたか。 | Calma. Onde desceu? | ochitsuite kudasai. doko de orimashita ka.",
  "Y: 名古屋駅です。 | Na estação de Nagoya. | Nagoya eki desu.",
  "P: カードは止めましたか。 | Bloqueou os cartões? | kādo wa tomemashita ka.",
  "Y: はい。連絡先を書きます。 | Sim. Vou escrever meu contato. | hai. renrakusaki o kakimasu.",
  "P: 見つかったら、すぐお電話します。 | Se acharmos, ligo em seguida. | mitsukattara, sugu odenwa shimasu."],
 slang=("Taku",["👛","#AE3EC9"],["F: マジか！財布やられたの？ | Sério?! Levaram sua carteira? | maji ka! saifu yarareta no?","Y: そう、駅でスられた。 | Isso, bateram minha carteira na estação. | sō, eki de surareta.","F: ありえない…。カードは？ | Inacreditável… E os cartões? | arienai…. kādo wa?","Y: すぐ止めたよ。焦った〜。 | Bloqueei na hora. Entrei em pânico. | sugu tometa yo. asetta~.","F: 見つかるといいね。 | Tomara que achem. | mitsukaru to ii ne.","Y: うん、交番に行ってきた。 | Aham, já fui ao posto policial. | un, kōban ni itte kita."],
  {"マジか":"sério?!","やられた":"fui lesado, levaram","スられた":"fui furtado (batedor de carteira)","ありえない":"inacreditável","焦った":"entrei em pânico, me apavorei"},["スられた","焦った"]),
